{
  "aktywnosci": [
    {
      "tytul": "Wędrówka bucików – poznajemy dawną tradycję andrzejkową",
      "opis": "Nauczyciel wprowadza dzieci w temat dawnych andrzejkowych zwyczajów i zaprasza do tradycyjnej zabawy w ustawianie butów w rzędzie. Dzieci zdejmują po jednym buciku i na zmianę przestawiają je jeden za drugim od najdalszego kąta sali w stronę drzwi. Podczas zabawy przedszkolaki ćwiczą cierpliwość, współpracę oraz umiejętność czekania na swoją kolej, a cała grupa kibicuje bucikowi, który jako pierwszy dotrze do progu."
    },
    {
      "tytul": "Taniec wokół czarodziejskiego klucza – zabawa ruchowo-muzyczna",
      "opis": "Nauczyciel kładzie na środku dywanu duży klucz wycięty z tektury i włącza skoczną, nastrojową muzykę. Dzieci poruszają się w kole w rytm melodii, naśladując podane przez nauczyciela figury (np. ciche skradanie się, podskoki, obroty). Gdy muzyka cichnie, zadaniem każdego przedszkolaka jest zastygnąć w bezruchu w wybranej, tajemniczej pozie."
    },
    {
      "tytul": "Czarodziejski klucz do dawnych opowieści – praca plastyczna",
      "opis": "Dzieci otrzymują szablony dużych kluczy wycięte z szarego lub żółtego kartonu. Zadaniem przedszkolaków jest ozdobienie swojego klucza za pomocą pasteli, kredek świecowych oraz naklejania drobnych kawałków bibuły lub kolorowego papieru. Na koniec nauczyciel pomaga zawiesić gotowe prace na tablicy, tworząc wspólną galerię andrzejkowych symboli."
    }
  ]
}
